const item = $input.first().json || {};
const body = item.body && typeof item.body === "object" ? item.body : item;
const inferred = String(body.mode || item.mode || "status");
const allowed = ["ingest", "produce", "release", "status", "full"];
const mode = allowed.includes(inferred) ? inferred : "status";
const slug = (body.slug || item.slug || "").toString().trim();
const rawPrivacy = (body.privacy || item.privacy || "private").toString().trim().toLowerCase();
const privacy = ["private", "unlisted", "public"].includes(rawPrivacy) ? rawPrivacy : "private";
const brief = (body.brief || body.source || item.brief || item.source || "").toString();
return [{
  json: {
    mode: mode,
    slug: slug,
    privacy: privacy,
    brief: brief,
    skip_build: Boolean(body.skip_build || item.skip_build),
    skip_publish: Boolean(body.skip_publish || item.skip_publish)
  }
}];

const raw = $input.first().json || {};
const payload = raw.output || raw;
const topics = payload.topics || [];
if (!topics.length) {
  return [{ json: { ok: false, action: "ingest", reason: "no_topics" } }];
}
return topics.map(function (topic) {
  return {
    json: {
      slug: String(topic.slug || "").trim(),
      title: String(topic.title || "").trim(),
      series: topic.series === "Zahl" ? "Zahl" : "System",
      state: "backlog",
      privacy: "private"
    }
  };
});

const items = $input.all();
const first = items[0] ? items[0].json : {};
if (first.reason === "no_topics") {
  return [{ json: { ok: false, action: "ingest", reason: "no_topics" } }];
}
const slugs = items.map(function (item) { return item.json.slug; }).filter(Boolean);
return [{ json: { ok: true, action: "ingest", topic: slugs[0] || "", count: slugs.length, topics: slugs, privacy: "private" } }];

const wanted = $("Normalize").isExecuted ? String($("Normalize").item.json.slug || "") : String($json.slug || "");
const rows = $input.all().map(function (item) { return item.json; }).filter(function (row) { return row && row.slug; });
let picked = null;
if (wanted) {
  picked = rows.find(function (row) { return row.slug === wanted; }) || null;
}
if (!picked) {
  picked = rows.find(function (row) { return row.state === "backlog"; }) || null;
}
if (!picked) {
  return [{ json: { empty: true, reason: "queue_empty", mode: "produce", privacy: "private" } }];
}
return [{ json: { empty: false, mode: "produce", slug: picked.slug, title: picked.title || picked.slug, series: picked.series || "System", state: picked.state, privacy: "private" } }];

