const today = $now.setZone("Europe/Berlin").toISODate();
const rows = $input.all().map(function (item) { return item.json; }).filter(function (row) { return row && row.slug; });
const due = rows.filter(function (row) {
  if (!row.release_date) { return false; }
  const day = String(row.release_date).slice(0, 10);
  return day <= today;
});
if (!due.length) {
  return [{ json: { empty: true, reason: "nothing_due", action: "release", privacy: "private" } }];
}
const picked = due[0];
return [{ json: { empty: false, action: "release", slug: picked.slug, title: picked.title || picked.slug, state: picked.state, privacy: "private", release_date: picked.release_date } }];

const picked = $("Kalendertag waehlen").item.json;
const site = $("Site Health").item.json || {};
const schedule = $("Schedule Health").item.json || {};
const siteOk = Number(site.statusCode || 0) >= 200 && Number(site.statusCode || 0) < 400;
const scheduleOk = Number(schedule.statusCode || 0) >= 200 && Number(schedule.statusCode || 0) < 400;
return [{
  json: {
    ok: siteOk,
    action: "release_check",
    topic: picked.slug,
    privacy: "private",
    state: "awaiting_site_publication",
    youtube_public: false,
    health: { site: siteOk, schedule: scheduleOk },
    summary: "Fälligkeit geprüft; dieser Cloud-Workflow veröffentlicht weder Website noch YouTube. Website-Publikation separat ausführen; YouTube bleibt private bis zum eigenen publishAt."
  }
}];

const rows = $("12 Status Queue").all().map(function (item) { return item.json; }).filter(function (row) { return row && row.slug; });
const site = $("Status Site").item.json || {};
const schedule = $("Status Schedule").item.json || {};
const siteOk = Number(site.statusCode || 0) >= 200 && Number(site.statusCode || 0) < 400;
const scheduleOk = Number(schedule.statusCode || 0) >= 200 && Number(schedule.statusCode || 0) < 400;
return [{
  json: {
    ok: true,
    action: "status",
    privacy: "private",
    count: rows.length,
    next_content: rows.filter(function (row) { return row.state === "backlog"; }).slice(0, 8).map(function (row) { return row.slug; }),
    due_today: rows.filter(function (row) { return row.state === "produced" || row.state === "scheduled"; }).slice(0, 8).map(function (row) { return row.slug; }),
    health: { site: siteOk, schedule: scheduleOk }
  }
}];
